mapper.insert:
INSERT INTO MEDICAL_RECORD (
    MEDICAL_RECORD_NUMBER, MEMBER_NUMBER, DIAGNOSIS_NAME,
    START_DATE, RECORD_STATUS
) VALUES (
#{medicalRecordNumber}, #{memberNumber}, #{diagnosisName}, SYSDATE, #{recordStatus}
)

mapper.select:
SELECT MEMBER_NUMBER
FROM RECEPTIONIST_REGISTER
WHERE MEDICAL_NUMBER = #{medicalNumber}

SELECT r.MEDICAL_NUMBER , r.MEMBER_NUMBER , m.MEMBER_NAME ,CASE WHEN SUBSTR(m.RESIDENT_REGISTRATION_NUMBER, 7, 1) IN ('1', '2') THEN EXTRACT(YEAR FROM SYSDATE) - (1900 + TO_NUMBER(SUBSTR(m.RESIDENT_REGISTRATION_NUMBER, 1, 2))) WHEN SUBSTR(m.RESIDENT_REGISTRATION_NUMBER, 7, 1) IN ('3', '4') THEN EXTRACT(YEAR FROM SYSDATE) - (2000 + TO_NUMBER(SUBSTR(m.RESIDENT_REGISTRATION_NUMBER, 1, 2))) ELSE 0 END AS AGE
, CASE WHEN MOD(TO_NUMBER(SUBSTR(m.RESIDENT_REGISTRATION_NUMBER, 7, 1)), 2) = 1 THEN '남' ELSE '여' END AS GENDER
FROM RECEPTIONIST_REGISTER r JOIN MEMBER m ON r.MEMBER_NUMBER = m.MEMBER_NUMBER WHERE r.MEDICAL_NUMBER = #{medicalNumber}

mapper.insert:
INSERT INTO
OUTPATIENTNURSE_INJECTION (
    MEDICAL_NUMBER, MEDICINE_CODE, DOSAGE, UNIT, FREQUENCY, INJECTED_YN, INJECTION_ORDER_TIME
) VALUES (
#{medicalNumber}, #{medicineCode}, #{dosage}, #{unit}, #{frequency}, 'N', SYSDATE
)

INSERT INTO
PHYSICALTHERAPIST_RECORDS (
    TREATMENT_NUMBER, MEDICAL_NUMBER, TREATMENT_ITEM_NAME, THERAPY_TYPE, TREATMENT_STATUS, DATE_OF_TREATMENT
) VALUES (
    PHYSICALTHERAPIST_RECORDS_SEQ.NEXTVAL, #{medicalNumber}, #{treatmentItemName}, #{therapyType}, '대기', SYSDATE
)

mapper.select:
SELECT MEDICAL_RECORD_NUMBER
FROM RECEPTIONIST_REGISTER
WHERE MEDICAL_NUMBER = #{medicalNumber}

SELECT DIAGNOSIS_NAME
FROM MEDICAL_RECORD
WHERE MEDICAL_RECORD_NUMBER = #{medicalRecordNumber}

mapper.update:
UPDATE MEDICAL_RECORD
SET DIAGNOSIS_NAME = #{diagnosisName}
WHERE MEDICAL_RECORD_NUMBER = #{medicalRecordNumber}

mapper.select:
SELECT * FROM ( SELECT '의약품' AS PRESCRIPTION_TYPE , COALESCE(nameCode.CODENAME_1, mc.MEDICINE_NAME) AS ITEM_NAME , d.TOTAL_QTY || '정 x 일' || d.FREQUENCY || '회 x ' || d.NUMBER_OF_DAYS_ADMINISTERED || '일' AS DETAIL , TO_CHAR(d.PRESCRIPTION_DATE, 'YYYY-MM-DD HH24:MI') AS PRESCRIPTION_DATE , CASE WHEN d.PRESCRIPTION_STATUS = 'Y' THEN '조제완료' ELSE '조제대기' END AS STATUS , d.MEDICAL_NUMBER AS MEDICAL_NUMBER , d.MEDICINE_CODE AS MEDICINE_CODE , TO_CHAR(NULL) AS TREATMENT_NUMBER , TO_CHAR(d.TOTAL_QTY) AS QTY , '정' AS UNIT , TO_CHAR(d.FREQUENCY) AS FREQUENCY , TO_CHAR(d.NUMBER_OF_DAYS_ADMINISTERED) AS DAYS , CASE WHEN d.PRESCRIPTION_STATUS = 'N' THEN 'Y' ELSE 'N' END AS EDITABLE FROM DOCTOR_PRESCRIPTION d
JOIN RECEPTIONIST_REGISTER r ON d.MEDICAL_NUMBER = r.MEDICAL_NUMBER JOIN MEDICINE mc ON d.MEDICINE_CODE = mc.MEDICINE_CODE LEFT JOIN COMMONCODE nameCode ON nameCode.COMMONCODE_NUMBER = mc.MEDICINE_NAME AND nameCode.COMMONCODE = 'M' WHERE r.MEDICAL_RECORD_NUMBER = #{medicalRecordNumber}
UNION ALL
SELECT '주사' AS PRESCRIPTION_TYPE , COALESCE(nameCode2.CODENAME_1, mc.MEDICINE_NAME) AS ITEM_NAME , j.DOSAGE || COALESCE(unitCode2.CODENAME_1, j.UNIT) || ' x 일' || j.FREQUENCY || '회' AS DETAIL , TO_CHAR(j.INJECTION_ORDER_TIME, 'YYYY-MM-DD HH24:MI') AS PRESCRIPTION_DATE , CASE WHEN j.INJECTED_YN = 'Y' THEN '투여완료' ELSE '투여대기' END AS STATUS , j.MEDICAL_NUMBER AS MEDICAL_NUMBER , j.MEDICINE_CODE AS MEDICINE_CODE , TO_CHAR(NULL) AS TREATMENT_NUMBER , j.DOSAGE AS QTY , COALESCE(unitCode2.CODENAME_1, j.UNIT) AS UNIT , j.FREQUENCY AS FREQUENCY , TO_CHAR(NULL) AS DAYS , CASE WHEN j.INJECTED_YN = 'N' THEN 'Y' ELSE 'N' END AS EDITABLE FROM OUTPATIENTNURSE_INJECTION j JOIN RECEPTIONIST_REGISTER r ON j.MEDICAL_NUMBER = r.MEDICAL_NUMBER JOIN MEDICINE mc ON j.MEDICINE_CODE = mc.MEDICINE_CODE LEFT JOIN COMMONCODE nameCode2 ON nameCode2.COMMONCODE_NUMBER = mc.MEDICINE_NAME AND nameCode2.COMMONCODE = 'M' LEFT JOIN COMMONCODE unitCode2 ON unitCode2.COMMONCODE_NUMBER = j.UNIT AND unitCode2.COMMONCODE = 'U' WHERE r.MEDICAL_RECORD_NUMBER = #{medicalRecordNumber}
UNION ALL
SELECT '물리치료' AS PRESCRIPTION_TYPE , TREATMENT_ITEM_NAME AS ITEM_NAME , THERAPY_TYPE AS DETAIL , TO_CHAR(DATE_OF_TREATMENT, 'YYYY-MM-DD HH24:MI') AS PRESCRIPTION_DATE , CASE WHEN TREATMENT_STATUS = '대기' THEN '치료대기' WHEN TREATMENT_STATUS = '치료중' THEN '치료중' WHEN TREATMENT_STATUS = '치료완료' THEN '치료완료' ELSE TREATMENT_STATUS END AS STATUS , pr.MEDICAL_NUMBER AS MEDICAL_NUMBER , TO_CHAR(NULL) AS MEDICINE_CODE , TO_CHAR(pr.TREATMENT_NUMBER) AS TREATMENT_NUMBER , TO_CHAR(NULL) AS QTY , TO_CHAR(NULL) AS UNIT , TO_CHAR(NULL) AS FREQUENCY , TO_CHAR(NULL) AS DAYS , CASE WHEN TREATMENT_STATUS = '대기' THEN 'Y' ELSE 'N' END AS EDITABLE FROM PHYSICALTHERAPIST_RECORDS pr JOIN RECEPTIONIST_REGISTER r ON pr.MEDICAL_NUMBER = r.MEDICAL_NUMBER WHERE r.MEDICAL_RECORD_NUMBER = #{medicalRecordNumber} ) ORDER BY PRESCRIPTION_DATE ASC

mapper.insert:
INSERT INTO RECEPTIONIST_DOCUMENTS (
RECEIVE_NUMBER, MEDICAL_NUMBER, RECEIVE_USE, RECEIVE_DATE,
RECEIVE_STATE, DOCUMENT_CONTENTS, DOCUMENT_TYPE
) VALUES (
RECEPTIONIST_DOCUMENTS_SEQ.NEXTVAL, #{medicalNumber}, #{receiveUse}, SYSDATE,
'접수', #{documentContents}, #{documentType}
)

mapper.update:
UPDATE MEDICAL_RECORD
SET RECORD_STATUS = '종료'
WHERE MEDICAL_RECORD_NUMBER = #{medicalRecordNumber}

UPDATE DOCTOR_PRESCRIPTION
SET TOTAL_QTY = #{qty},
FREQUENCY = #{frequency},
NUMBER_OF_DAYS_ADMINISTERED = #{days}
WHERE MEDICAL_NUMBER = #{medicalNumber}
AND MEDICINE_CODE = #{medicineCode}
AND PRESCRIPTION_STATUS = 'N'

mapper.delete:
DELETE FROM DOCTOR_PRESCRIPTION
WHERE MEDICAL_NUMBER = #{medicalNumber}
AND MEDICINE_CODE = #{medicineCode}
AND PRESCRIPTION_STATUS = 'N'

mapper.update:
UPDATE OUTPATIENTNURSE_INJECTION
SET DOSAGE = #{qty},
FREQUENCY = #{frequency}
WHERE MEDICAL_NUMBER = #{medicalNumber}
AND MEDICINE_CODE = #{medicineCode}
AND INJECTED_YN = 'N'

mapper.delete:
DELETE FROM OUTPATIENTNURSE_INJECTION
WHERE MEDICAL_NUMBER = #{medicalNumber}
AND MEDICINE_CODE = #{medicineCode}
AND INJECTED_YN = 'N'

DELETE FROM PHYSICALTHERAPIST_RECORDS
WHERE TREATMENT_NUMBER = #{treatmentNumber}
AND TREATMENT_STATUS = '대기'
